// This session's numbers for the Usage and Agents rooms: what the engine
// measures (context, rate limits, cost), what each turn used (tokens, cache),
// how long each tool call took, and which subagents ran. Plain logic: the
// hooks module feeds it from session.measure, turn.complete, tool.call and
// agent.spawn.

import { findSecret } from "./share.mjs";

const COST_SAMPLES = 240;      // about two hours at one sample per 30 s
const SAMPLE_EVERY_MS = 30_000;
const DURATIONS = 200;         // per tool, for the percentiles
const FEED = 40;               // newest tool calls kept for the live feed
const BURN_WINDOW_MS = 15 * 60_000;

export function createUsage() {
  return {
    measured: false,
    context: null,             // { tokens, window, percent }
    breakdown: null,           // the /context breakdown, fetched when asked for
    showBreakdown: false,
    rateLimits: [],            // [{ kind, percentUsed, resetsAt }]
    hasLimits: false,          // ever reported a window (a subscription, not an API key)
    ctxHistory: [],            // context tokens after each main-loop turn, oldest first (the band's chart)
    cost: null,                // { usd }
    startedAt: null,
    model: null,
    costSamples: [],           // [{ at, usd }]
    tokens: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
    tools: new Map(),          // tool name → { count, errors, durations }
    calls: new Map(),          // call key → feed entry, while it runs
    feed: [],                  // [{ key, tool, agentId, summary, at, ms, isError, done }], oldest first
    agents: new Map(),         // agent id → { id, type, description, status, parentId, startedAt, endedAt, tools }
    callsNamed: 0,             // tool calls named by their results, so the strata redraw
    steps: [],                 // the main loop's requests, oldest first (see stepStarted)
    overhead: null,            // { tokens, biggest: { name, tokens } }: what every request carries before the conversation
    overheadAt: 0,             // stepN when it was last read
    stepIn: [],                // what the next request carries that the last one didn't: [{ kind, label, chars }]
    stepN: 0,
    activity: { state: "idle", tool: null, since: 0 },   // idle | thinking | tool
  };
}

// ---------------------------------------------------------------- engine figures

// A session.measure event or a $.session.usage() answer.
export function applyMeasure(u, m, now) {
  if (!m) return false;
  u.measured = true;
  if (m.context) u.context = { tokens: m.context.tokens, window: m.context.window, percent: m.context.percent };
  if (Array.isArray(m.rateLimits)) {
    u.rateLimits = m.rateLimits;
    if (m.rateLimits.length) u.hasLimits = true;   // a subscription: its windows always show
  }
  if (typeof m.startedAt === "number") u.startedAt = m.startedAt;
  if (m.cost && typeof m.cost.usd === "number") {
    u.cost = { usd: m.cost.usd };
    const last = u.costSamples.at(-1);
    if (!last || last.usd !== m.cost.usd || now - last.at >= SAMPLE_EVERY_MS) {
      u.costSamples.push({ at: now, usd: m.cost.usd });
      if (u.costSamples.length > COST_SAMPLES) u.costSamples.splice(0, u.costSamples.length - COST_SAMPLES);
    }
  }
  return true;
}

// The context's fill after a main-loop turn, for the band's chart.
const CTX_HISTORY = 12;
export function recordTurnContext(u) {
  const t = u.context?.tokens;
  if (t == null) return false;
  u.ctxHistory.push(t);
  if (u.ctxHistory.length > CTX_HISTORY) u.ctxHistory.splice(0, u.ctxHistory.length - CTX_HISTORY);
  return true;
}

// What the band needs back after a reload (the module starts over, the
// session does not): the tokens so far and the context after each turn.
export function usageSnapshot(u, at) {
  return { at, tokens: { ...u.tokens }, ctxHistory: [...u.ctxHistory] };
}

export function restoreUsage(u, saved) {
  if (!saved || typeof saved !== "object") return false;
  const t = saved.tokens ?? {};
  for (const k of ["input", "output", "cacheRead", "cacheWrite"]) if (Number.isFinite(t[k])) u.tokens[k] = Math.max(u.tokens[k], t[k]);
  if (Array.isArray(saved.ctxHistory) && !u.ctxHistory.length) u.ctxHistory = saved.ctxHistory.filter(Number.isFinite).slice(-CTX_HISTORY);
  return true;
}

// What one turn used (turn.complete's `usage`), the main loop's or a subagent's.
export function applyTurnUsage(u, usage) {
  if (!usage) return false;
  u.tokens.input += usage.input_tokens ?? 0;
  u.tokens.output += usage.output_tokens ?? 0;
  u.tokens.cacheRead += usage.cache_read_input_tokens ?? 0;
  u.tokens.cacheWrite += usage.cache_creation_input_tokens ?? 0;
  if (usage.model) u.model = usage.model;
  return true;
}

export function totalTokens(u) {
  const t = u.tokens;
  return t.input + t.output + t.cacheRead + t.cacheWrite;
}

// The windows to show, 5-hour and 7-day first and always (a window that just
// reset has no reading until the next reply: its percent is null), then any
// others the account has. None at all for an account without windows.
const MAIN_WINDOWS = ["five_hour", "seven_day"];
export function limitWindows(u) {
  if (!u.hasLimits && !u.rateLimits.length) return [];
  const main = MAIN_WINDOWS.map((kind) => u.rateLimits.find((l) => l.kind === kind) ?? { kind, percentUsed: null });
  return [...main, ...u.rateLimits.filter((l) => !MAIN_WINDOWS.includes(l.kind))];
}

// The share of input read from the prompt cache, 0-100, or null before any.
export function cacheRatio(u) {
  const t = u.tokens;
  const input = t.input + t.cacheRead + t.cacheWrite;
  return input ? (t.cacheRead / input) * 100 : null;
}

// Dollars per hour over the last quarter hour, or null with too little to go on.
export function burnRate(u, now) {
  const recent = u.costSamples.filter((s) => now - s.at <= BURN_WINDOW_MS);
  if (recent.length < 2) return null;
  const first = recent[0];
  const last = recent.at(-1);
  const hours = (last.at - first.at) / 3_600_000;
  if (hours < 5 / 60) return null;   // a few minutes say little about an hour
  return (last.usd - first.usd) / hours;
}

// Spend per bucket over the last `n` buckets, oldest first: the sparkline.
export function spendSeries(u, now, n = 12, bucketMs = 5 * 60_000) {
  const out = new Array(n).fill(0);
  const s = u.costSamples;
  for (let i = 1; i < s.length; i++) {
    const back = Math.floor((now - s[i].at) / bucketMs);
    if (back < 0 || back >= n) continue;
    out[n - 1 - back] += Math.max(0, s[i].usd - s[i - 1].usd);
  }
  return out;
}

// ---------------------------------------------------------------- tool calls

// A few words on what a call is about, with anything that looks like a
// secret masked: the command for Bash, a file's name, a search pattern.
export function toolSummary(tool, input = {}) {
  const base = (p) => String(p ?? "").split("/").filter(Boolean).at(-1) ?? "";
  let s;
  switch (tool) {
    // A leading "cd <dir> &&" says where, not what: the command after it is the news.
    case "Bash": s = String(input.command ?? "").replace(/^\s*cd\s+(?:"[^"]*"|'[^']*'|\S+)\s*(?:&&|;)\s*/, ""); break;
    case "Read": case "Write": case "Edit": case "NotebookEdit": s = base(input.file_path ?? input.notebook_path); break;
    case "Grep": s = input.pattern ? `"${input.pattern}"` : ""; break;
    case "Glob": s = input.pattern; break;
    case "WebFetch": s = input.url; break;
    case "WebSearch": s = input.query; break;
    case "Agent": case "Task": s = input.description; break;
    default: s = input.description ?? input.command ?? input.query ?? "";
  }
  s = String(s ?? "").replace(/\s+/g, " ").trim();
  if (findSecret(s)) return "(hidden: looks secret)";
  return s.slice(0, 80);
}

let seq = 0;

export function toolStarted(u, { tool, agentId, input, at }) {
  const key = `c${++seq}`;
  const entry = { key, tool, agentId: agentId ?? null, summary: toolSummary(tool, input), at, ms: null, isError: false, done: false };
  u.calls.set(key, entry);
  u.feed.push(entry);
  if (u.feed.length > FEED) u.feed.splice(0, u.feed.length - FEED);
  if (agentId) {
    // Only agents the session spawned or lists: the engine's own loops
    // (compaction, memory) carry ids nothing else names.
    const a = u.agents.get(agentId);
    if (a) a.tools.set(tool, (a.tools.get(tool) ?? 0) + 1);
  } else {
    u.activity = { state: "tool", tool, since: at };
  }
  return key;
}

export function toolEnded(u, key, { at, isError = false }) {
  const entry = u.calls.get(key);
  if (!entry) return false;
  u.calls.delete(key);
  entry.ms = Math.max(0, at - entry.at);
  entry.isError = isError;
  entry.done = true;
  const t = u.tools.get(entry.tool) ?? { count: 0, errors: 0, durations: [] };
  t.count++;
  if (isError) t.errors++;
  t.durations.push(entry.ms);
  if (t.durations.length > DURATIONS) t.durations.shift();
  u.tools.set(entry.tool, t);
  if (!entry.agentId && u.activity.state === "tool") u.activity = { state: "thinking", tool: null, since: at };
  return true;
}

export function percentile(values, p) {
  if (!values.length) return null;
  const sorted = [...values].sort((a, b) => a - b);
  const i = Math.min(sorted.length - 1, Math.max(0, Math.ceil((p / 100) * sorted.length) - 1));
  return sorted[i];
}

// One row per tool, the most time spent first.
export function toolRows(u) {
  return [...u.tools.entries()].map(([name, t]) => ({
    name,
    count: t.count,
    errors: t.errors,
    p50: percentile(t.durations, 50),
    p95: percentile(t.durations, 95),
    total: t.durations.reduce((a, b) => a + b, 0),
  })).sort((a, b) => b.total - a.total || b.count - a.count);
}

export function runningCalls(u) {
  return [...u.calls.values()];
}

// ---------------------------------------------------------------- turns

export function turnStarted(u, at) {
  u.activity = { state: "thinking", tool: null, since: at };
}

export function turnEnded(u, at) {
  u.activity = { state: "idle", tool: null, since: at };
}

// ---------------------------------------------------------------- requests

// Each request the main loop sends the model (one prompt takes several: a
// tool's answer goes back in a new one), with the API's own usage for it,
// what it carried that was new (the prompt, tool results) and what it
// answered with. The engine gives one total per request, so the growth since
// the request before is split across its new pieces by size: an estimate,
// which is what tells you that a Read took 6k and a Bash 200.
const STEPS = 30;

export function stepPrompt(u, text) {
  if (text) u.stepIn.push({ kind: "prompt", label: "prompt", chars: String(text).length });
}

// A tool's answer, named by what it was about ("Read metrics.mjs") so the
// card can say which one without numbering requests.
export function stepToolResult(u, tool, chars, summary = "") {
  const about = summary && !summary.startsWith("(hidden") ? ` ${summary.length > 24 ? `${summary.slice(0, 23)}…` : summary}` : "";
  u.stepIn.push({ kind: "tool", label: `${tool}${about}`, chars: Math.max(0, chars) });
  // The request that called it learns what the call was about, so its
  // output can be named by it ("Claude's Edit pane.ts").
  const call = u.steps.at(-1)?.tools.find((c) => c.tool === tool && c.about == null);
  if (call) { call.about = about; u.callsNamed++; }
}

export function stepStarted(u, { turnId, index = 0, at }) {
  const step = { n: ++u.stepN, turnId, index, at, status: "streaming", input: null, output: null, cacheRead: 0, added: u.stepIn, grown: null, tools: [], stopReason: null, isCompacted: false };
  u.stepIn = [];
  u.steps.push(step);
  if (u.steps.length > STEPS) u.steps.splice(0, u.steps.length - STEPS);
  return step;
}

export function stepToolUse(step, name) {
  if (step && name) step.tools.push({ tool: name, about: null });
}

// A request that failed (no usage: the stream broke or was dropped) hands
// what it carried to the next, which sends it again.
export function stepEnded(u, step, usage, stopReason) {
  if (!step) return false;
  step.stopReason = stopReason ?? null;
  if (!usage) {
    step.status = "failed";
    u.stepIn = [...step.added, ...u.stepIn];
    step.added = [];
    return true;
  }
  step.status = "done";
  step.input = (usage.input_tokens ?? 0) + (usage.cache_read_input_tokens ?? 0) + (usage.cache_creation_input_tokens ?? 0);
  step.output = usage.output_tokens ?? 0;
  step.cacheRead = usage.cache_read_input_tokens ?? 0;
  // Grown since the last request that came back, a failed one between them aside.
  const prev = u.steps.slice(0, u.steps.indexOf(step)).findLast((s) => s.status === "done") ?? null;
  if (prev?.input != null && prev.output != null) {
    if (step.input < prev.input) step.isCompacted = true;
    else step.grown = Math.max(0, step.input - prev.input - prev.output);
  }
  if (step.grown != null) splitBySize(step.added, step.grown);
  return true;
}

// Spreads `total` over `pieces` by their characters; the parts sum to it.
function splitBySize(pieces, total) {
  const sum = pieces.reduce((n, p) => n + Math.max(1, p.chars), 0);
  let left = total;
  pieces.forEach((p, i) => {
    p.tokens = i === pieces.length - 1 ? left : Math.round((total * Math.max(1, p.chars)) / sum);
    left -= p.tokens;
  });
}

// What every request carries before the conversation, from the /context
// breakdown: its used rows (system prompt, tools, MCP tools, memory files,
// skills, agents) less the conversation itself.
const NOT_OVERHEAD = /messages|free space|autocompact|reserved/i;
export function applyOverhead(u, breakdown) {
  const rows = (breakdown?.categories ?? []).filter((c) => (c.kind ? c.kind === "used" : true) && !c.isDeferred && c.tokens > 0 && !NOT_OVERHEAD.test(c.name));
  if (!rows.length) return false;
  const biggest = rows.reduce((a, b) => (b.tokens > a.tokens ? b : a));
  u.overhead = { tokens: rows.reduce((n, c) => n + c.tokens, 0), biggest: { name: biggest.name, tokens: biggest.tokens } };
  u.overheadAt = u.stepN;
  return true;
}

// Whether to read the breakdown again: never read, or a few requests old.
export function wantsOverhead(u) {
  return u.steps.length > 0 && (!u.overhead || u.stepN - u.overheadAt >= 8);
}

// The context as strata, for the Requests card: one column per request (what
// it sent), then one for the next (the context now). Each thing that came
// into the conversation is a layer from the request that first carried it
// on, so a tool result read once is seen riding along in every column after.
// The few biggest get layers of their own; the rest is "conversation". Under
// them all is the bedrock: what was already there when the first column was
// sent, the overhead every request carries and any conversation from before
// we started watching, drawn apart since to scale it would flatten what
// comes after (a session hours long has hundreds of k of it). Column heights
// are the API's own figures.
const NAMED = 4;
// Worked out again only when a request starts or ends or the overhead is
// read: a redraw draws the card and its tips from one, not one each.
const strataSeen = new WeakMap();   // usage → { sig, byCols: Map }
export function strata(u, maxCols = 12) {
  const sig = `${u.stepN}:${u.callsNamed}:${u.steps.map((s) => s.status[0]).join("")}:${u.overhead?.tokens ?? ""}`;
  let seen = strataSeen.get(u);
  if (seen?.sig !== sig) strataSeen.set(u, seen = { sig, byCols: new Map() });
  if (!seen.byCols.has(maxCols)) seen.byCols.set(maxCols, layered(u, maxCols));
  return seen.byCols.get(maxCols);
}

function layered(u, maxCols) {
  let from = 0;
  const done = u.steps.filter((s) => s.status === "done" && s.input != null);
  done.forEach((s, i) => { if (s.isCompacted) from = i; });
  const since = done.slice(from);
  if (!since.length) return null;
  const first = since[0];
  const firstAdded = first.added.reduce((n, p) => n + (p.tokens ?? Math.round(p.chars / 4)), 0);
  const start = Math.max(0, first.input - firstAdded);
  const bed = Math.min(u.overhead?.tokens ?? start, start);
  const items = [];
  since.forEach((s, k) => {
    for (const p of s.added) {
      const tokens = p.tokens ?? Math.round(p.chars / 4);
      items.push({ name: p.kind === "prompt" ? "your prompt" : p.label, kind: p.kind, n: s.n, enter: k, tokens });
    }
    if (s.output) items.push({ name: s.tools.length ? toolCallsName(s.tools) : "Claude's reply", kind: "answer", n: s.n, enter: k + 1, tokens: s.output });
  });
  const named = [...items].filter((it) => it.tokens >= 300).sort((a, b) => b.tokens - a.tokens).slice(0, NAMED).sort((a, b) => a.enter - b.enter || a.n - b.n);
  const last = since.at(-1);
  const all = [...since.map((s, k) => ({ label: k ? "older" : "first", k, total: s.input })), { label: "next", k: since.length, total: last.input + (last.output ?? 0) }];
  const cols = all.slice(-maxCols);
  // Named by what they are; two alike ("Claude's reply") are told apart by count.
  const seen = new Map();
  const layers = named.map((it) => {
    const k = (seen.get(it.name) ?? 0) + 1;
    seen.set(it.name, k);
    return { name: k > 1 ? `${it.name} (${k})` : it.name, kind: it.kind, sizes: cols.map((c) => (c.k >= it.enter ? it.tokens : 0)) };
  });
  const talk = cols.map((c, i) => Math.max(0, c.total - start - layers.reduce((n, l) => n + l.sizes[i], 0)));
  return {
    bedrock: bed,
    bedrockKnown: !!u.overhead,
    earlier: start - bed,
    cols: cols.map((c) => ({ label: c.label, above: Math.max(0, c.total - start) })),
    layers: [{ name: "conversation", kind: "talk", sizes: talk }, ...layers],
    compacted: from > 0 || first.isCompacted,
    sent: since.length,
  };
}

// A request's tool calls, named by the one that wrote the most: a Write or an
// Edit carries its content, the rest little more than a path or a command.
const WRITES = new Set(["Write", "Edit", "NotebookEdit"]);
function toolCallsName(calls) {
  const top = calls.find((c) => WRITES.has(c.tool)) ?? calls[0];
  const more = calls.length > 1 ? ` and ${calls.length - 1} more` : "";
  return `Claude's ${top.tool}${top.about ?? ""}${more}`;
}

// Two or three things worth knowing, in plain words: how much of a request
// is the overhead, the biggest thing riding along, and what the next one sends.
export function contextTips(u) {
  const st = strata(u);
  if (!st) return [];
  const tips = [];
  const last = u.steps.filter((s) => s.status === "done" && s.input != null).at(-1);
  if (st.bedrockKnown && last?.input) {
    const pct = Math.round((st.bedrock / last.input) * 100);
    const big = u.overhead.biggest;
    tips.push({ icon: "⚙", parts: [["Fixed overhead", true], [` (${fmtK(st.bedrock)}): sent with every request, ${pct}% of the last request.`, false], ...(big ? [[` Biggest: ${big.name} (${fmtK(big.tokens)}).`, false]] : [])] });
  }
  const top = st.layers.slice(1).reduce((a, l) => (!a || l.sizes.at(-1) > a.sizes.at(-1) ? l : a), null);
  const tok = top?.sizes.at(-1) ?? 0;
  if (top && tok >= 1000) {
    const rides = top.sizes.slice(0, -1).filter((n) => n > 0).length;
    const what = top.name.charAt(0).toUpperCase() + top.name.slice(1);
    // Said so it can't read as fetched again: it came in once, and is resent,
    // with what that has added up to.
    const once = top.kind === "answer" ? "written once" : top.kind === "prompt" ? "sent once" : /^Read\b/.test(top.name) ? "read once" : "came back once";
    const resent = rides ? `resent ${rides} time${rides === 1 ? "" : "s"} so far (${fmtK(rides * tok)} sent in all).` : "resent with every request from now on.";
    tips.push({ icon: "⇠", parts: [[what, true], [` (${fmtK(tok)}): ${once}, ${resent}`, false]] });
  }
  const next = st.bedrock + st.earlier + (st.cols.at(-1)?.above ?? 0);
  const pct = u.context?.percent;
  tips.push({ icon: "→", parts: [["The next request sends ", false], [fmtK(next), true], [Number.isFinite(pct) ? `, ${Math.round(pct)}% of the window.` : ".", false], ...(pct >= 80 ? [[" Compaction is near.", false]] : [])] });
  return tips;
}

function fmtK(n) {
  if (n < 1000) return String(Math.round(n));
  return n < 10_000 ? `${(n / 1000).toFixed(1).replace(/\.0$/, "")}k` : `${Math.round(n / 1000)}k`;
}

// ---------------------------------------------------------------- subagents

function agentEntry(u, id, at) {
  let a = u.agents.get(id);
  if (!a) {
    a = { id, type: "agent", description: "", status: "running", parentId: null, startedAt: at, endedAt: null, tools: new Map() };
    u.agents.set(id, a);
  }
  return a;
}

export function agentSpawned(u, { id, type, description, parentId, at }) {
  if (!id) return false;
  const a = agentEntry(u, id, at);
  a.type = type || a.type;
  a.description = description || a.description;
  a.parentId = parentId ?? a.parentId;
  a.startedAt = Math.min(a.startedAt, at);
  return true;
}

const ENDED = new Set(["completed", "failed", "killed"]);

// $.agent.list(): the engine's word on each agent's status.
export function applyAgentList(u, list, now) {
  let changed = false;
  for (const info of list ?? []) {
    const a = agentEntry(u, info.id, now);
    const was = a.status;
    a.type = info.type || a.type;
    a.description = info.description || a.description;
    a.parentId = info.parentId ?? a.parentId;
    a.status = info.status;
    if (ENDED.has(info.status) && !a.endedAt) a.endedAt = now;
    if (was !== a.status) changed = true;
  }
  return changed;
}

// Agents in tree order: each one followed by those it spawned, newest first
// at each level. Each row carries its depth and whether it is the last child.
export function agentTree(u) {
  const all = [...u.agents.values()];
  // An agent whose parent isn't known is drawn at the top level.
  const parentOf = (a) => (a.parentId && u.agents.has(a.parentId) ? a.parentId : null);
  const out = [];
  const walk = (pid, depth) => {
    const list = all.filter((a) => parentOf(a) === pid).sort((a, b) => b.startedAt - a.startedAt);
    list.forEach((a, i) => {
      out.push({ agent: a, depth, last: i === list.length - 1 });
      walk(a.id, depth + 1);
    });
  };
  walk(null, 0);
  return out;
}

export function agentCounts(u) {
  let running = 0;
  let done = 0;
  for (const a of u.agents.values()) {
    if (ENDED.has(a.status)) done++;
    else running++;
  }
  return { running, done };
}

export function isEnded(status) {
  return ENDED.has(status);
}

// The tool an agent used most: "Read ×14".
export function topTool(agent) {
  let best = null;
  for (const [name, n] of agent.tools) if (!best || n > best[1]) best = [name, n];
  return best ? `${best[0]} ×${best[1]}` : "";
}

files.hooks/github.mjs:
// The Git room's data: the local branch from `git status`, and pull requests,
// reviews, Actions runs, issues and Dependabot alerts from the `gh` CLI,
// signed in as the person already is. Nothing is stored and no token passes
// through here. `run(argv)` comes from the hooks module ($.process.run).

const PR_FIELDS = "number,title,state,isDraft,url,author,headRefName,reviewDecision,statusCheckRollup,updatedAt";
const PR_VIEW_FIELDS = `${PR_FIELDS},mergeable,mergeStateStatus,reviews,reviewRequests`;

export function emptyGit() {
  return {
    status: "idle",       // idle | loading | ok | no-gh | no-auth | no-repo | error
    error: "",
    fetchedAt: 0,
    stale: false,         // the last refresh failed: what's shown is older
    me: null,             // the gh login
    repo: null,           // { name, url }
    local: null,          // { branch, ahead, behind, changed }
    pr: null,             // this branch's pull request
    prs: [],              // open pull requests
    reviewMe: [],         // numbers of open PRs that ask for my review
    runs: [],             // recent Actions runs
    issues: [],           // open issues assigned to me
    alerts: null,         // Dependabot alerts, or null when not readable
    log: [],              // the newest commits of every branch, laid out as a graph (layoutGraph)
  };
}

// ---------------------------------------------------------------- parsing

// `git status --porcelain=v2 --branch`
export function parseGitStatus(out) {
  const local = { branch: null, ahead: 0, behind: 0, changed: 0, upstream: null, unpushed: null };
  for (const line of String(out).split("\n")) {
    if (line.startsWith("# branch.head ")) local.branch = line.slice(14).trim();
    else if (line.startsWith("# branch.upstream ")) local.upstream = line.slice(18).trim();
    else if (line.startsWith("# branch.ab ")) {
      const m = /\+(\d+) -(\d+)/.exec(line);
      if (m) { local.ahead = Number(m[1]); local.behind = Number(m[2]); }
    } else if (/^[12u?] /.test(line)) local.changed++;
  }
  if (local.branch === "(detached)") local.branch = "detached";
  return local;
}

const FAILED = new Set(["FAILURE", "TIMED_OUT", "CANCELLED", "ACTION_REQUIRED", "STARTUP_FAILURE", "ERROR"]);

// A PR's checks as counts: passed, failed, still running.
export function checks(rollup) {
  const c = { pass: 0, fail: 0, pending: 0, total: 0 };
  for (const item of rollup ?? []) {
    c.total++;
    if (item.__typename === "StatusContext" || item.state) {
      if (item.state === "SUCCESS") c.pass++;
      else if (FAILED.has(item.state)) c.fail++;
      else c.pending++;
      continue;
    }
    if (item.status !== "COMPLETED") c.pending++;
    else if (FAILED.has(item.conclusion)) c.fail++;
    else c.pass++;
  }
  return c;
}

function prModel(p) {
  return {
    number: p.number,
    title: p.title ?? "",
    state: p.state ?? "OPEN",
    draft: !!p.isDraft,
    url: p.url,
    author: p.author?.login ?? "",
    branch: p.headRefName ?? "",
    decision: p.reviewDecision || null,     // APPROVED | CHANGES_REQUESTED | REVIEW_REQUIRED
    checks: checks(p.statusCheckRollup),
    updatedAt: Date.parse(p.updatedAt) || 0,
  };
}

// `gh pr view` adds who reviewed (each person's latest word) and who's asked.
export function parsePrView(p) {
  const pr = prModel(p);
  const latest = new Map();
  for (const r of p.reviews ?? []) {
    const who = r.author?.login;
    if (!who || r.state === "COMMENTED" || r.state === "PENDING") continue;
    latest.set(who, r.state);
  }
  pr.reviews = [...latest].map(([login, state]) => ({ login, state }));
  pr.requested = (p.reviewRequests ?? []).map((r) => r.login ?? r.name ?? r.slug).filter(Boolean);
  pr.mergeable = p.mergeable ?? "UNKNOWN";          // MERGEABLE | CONFLICTING | UNKNOWN
  pr.mergeState = p.mergeStateStatus ?? "UNKNOWN";  // CLEAN | BLOCKED | BEHIND | DIRTY | UNSTABLE | ...
  return pr;
}

export function parsePrList(list) {
  return (list ?? []).map(prModel);
}

// Recent runs, the newest of each workflow on each branch only: an older
// run that a newer one replaced (a failure since fixed) no longer counts.
export function parseRuns(list) {
  const seen = new Set();
  return (list ?? []).filter((r) => {
    const key = `${r.workflowName || r.name}\u0000${r.headBranch}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  }).map((r) => ({
    id: r.databaseId,
    name: r.workflowName || r.name || "workflow",
    branch: r.headBranch ?? "",
    status: r.status,                 // queued | in_progress | completed
    conclusion: r.conclusion || null, // success | failure | cancelled | skipped
    startedAt: Date.parse(r.createdAt) || 0,
    updatedAt: Date.parse(r.updatedAt) || 0,
    url: r.url,
  }));
}

export function parseIssues(list) {
  return (list ?? []).map((i) => ({
    number: i.number,
    title: i.title ?? "",
    url: i.url,
    labels: (i.labels ?? []).map((l) => l.name),
    updatedAt: Date.parse(i.updatedAt) || 0,
  }));
}

export function parseAlerts(list) {
  return (list ?? []).map((a) => ({
    number: a.number,
    pkg: a.dependency?.package?.name ?? a.security_vulnerability?.package?.name ?? "dependency",
    severity: a.security_advisory?.severity ?? a.security_vulnerability?.severity ?? "unknown",
    url: a.html_url,
  }));
}

// `git log` over every branch and remote, one record a commit (fields split
// by \x1f, records by \x1e): hash, parents, refs, subject, commit time.
export const LOG_FORMAT = "%H%x1f%P%x1f%D%x1f%s%x1f%ct%x1e";
export function parseLog(out) {
  return String(out ?? "").split("\x1e").map((r) => r.replace(/^\n/, "")).filter((r) => r.includes("\x1f")).map((r) => {
    const [hash, parents, refs, subject, ct] = r.split("\x1f");
    let head = null;
    const names = String(refs ?? "").split(",").map((x) => x.trim()).filter(Boolean).flatMap((x) => {
      if (x.startsWith("HEAD -> ")) { head = x.slice(8); return [head]; }
      if (x === "HEAD" || x.endsWith("/HEAD") || x.startsWith("tag: ")) return x.startsWith("tag: ") ? [x.slice(5)] : [];
      return [x];
    });
    return { hash, parents: String(parents ?? "").split(" ").filter(Boolean), refs: names, head, subject: subject ?? "", at: Number(ct) * 1000 || 0 };
  });
}

// Lanes for a graph of `commits` (newest first): each row's commit column,
// the lanes coming in at its top and going out at its bottom (a lane holds
// the hash it waits for), so a drawing can run a line from each lane above
// to where that hash is below. Lanes past `maxLanes` are dropped.
export function layoutGraph(commits, maxLanes = 6) {
  let lanes = [];
  return commits.map((c) => {
    const before = lanes.slice();
    let col = lanes.indexOf(c.hash);
    if (col < 0) { col = lanes.indexOf(null); if (col < 0) col = lanes.length; }
    const after = lanes.map((h) => (h === c.hash ? null : h));
    after[col] = c.parents[0] ?? null;
    for (const p of c.parents.slice(1)) {
      if (after.includes(p)) continue;
      const free = after.indexOf(null);
      if (free >= 0) after[free] = p; else after.push(p);
    }
    while (after.length && after.at(-1) == null) after.pop();
    lanes = after.slice(0, maxLanes);
    return { ...c, col: Math.min(col, maxLanes - 1), before: before.slice(0, maxLanes), after: lanes.slice() };
  });
}

// ---------------------------------------------------------------- fetching

const NO_AUTH = /gh auth login|not logged in|authentication|HTTP 401/i;
const NO_PR = /no pull requests found|no open pull requests/i;
const NO_REMOTE = /no git remotes|none of the git remotes|not a github|could not determine/i;

function json(out) {
  try { return JSON.parse(out || "null"); } catch { return null; }
}

// Everything the room shows, fetched in parallel. `prev` is the last good
// snapshot: on a failed refresh it stays, marked stale.
export async function fetchGit(run, prev = emptyGit()) {
  const next = { ...emptyGit(), me: prev.me };
  let status;
  try {
    status = await run(["git", "status", "--porcelain=v2", "--branch"]);
  } catch (err) {
    return { ...prev, status: "error", error: `git: ${err?.message ?? err}`, stale: prev.status === "ok" };
  }
  if (status.exitCode !== 0) {
    return /not a git repository/i.test(status.stderr)
      ? { ...emptyGit(), status: "no-repo" }
      : { ...prev, status: "error", error: firstLine(status.stderr) || "git status failed", stale: prev.status === "ok" };
  }
  next.local = parseGitStatus(status.stdout);
  // The newest commits of every branch and remote, for the desktop's graph.
  try {
    const log = await run(["git", "log", "--branches", "--remotes", "--tags", "--date-order", "-n", "10", `--format=${LOG_FORMAT}`]);
    next.log = log.exitCode === 0 ? layoutGraph(parseLog(log.stdout)) : prev.log ?? [];
  } catch { next.log = prev.log ?? []; }
  // A branch that was never pushed has nothing to be ahead of: count its
  // commits past the main branch instead.
  if (!next.local.upstream && next.local.branch && next.local.branch !== "detached") {
    next.local.unpushed = await unpushed(run);
  }

  const gh = (args) => run(["gh", ...args]).then((r) => r, (err) => ({ thrown: err }));
  const [repo, me] = await Promise.all([
    gh(["repo", "view", "--json", "nameWithOwner,url"]),
    prev.me ? Promise.resolve(null) : gh(["api", "user", "--jq", ".login"]),
  ]);
  if (repo.thrown) return { ...emptyGit(), local: next.local, log: next.log, status: "no-gh" };
  if (repo.exitCode !== 0) {
    if (NO_AUTH.test(repo.stderr)) return { ...emptyGit(), local: next.local, log: next.log, status: "no-auth" };
    if (NO_REMOTE.test(repo.stderr)) return { ...emptyGit(), local: next.local, log: next.log, status: "ok", fetchedAt: Date.now(), error: "no GitHub remote" };
    return { ...prev, local: next.local, status: "error", error: firstLine(repo.stderr) || "gh failed", stale: prev.status === "ok" };
  }
  const r = json(repo.stdout);
  next.repo = { name: r?.nameWithOwner ?? "", url: r?.url ?? "" };
  if (me && me.exitCode === 0) next.me = me.stdout.trim() || null;

  const [view, list, mine, runs, issues, alerts] = await Promise.all([
    gh(["pr", "view", "--json", PR_VIEW_FIELDS]),
    gh(["pr", "list", "--state", "open", "--limit", "8", "--json", PR_FIELDS]),
    gh(["pr", "list", "--state", "open", "--search", "review-requested:@me", "--json", "number"]),
    gh(["run", "list", "--limit", "12", "--json", "databaseId,name,workflowName,headBranch,status,conclusion,createdAt,updatedAt,url"]),
    gh(["issue", "list", "--state", "open", "--assignee", "@me", "--limit", "6", "--json", "number,title,url,labels,updatedAt"]),
    gh(["api", "repos/{owner}/{repo}/dependabot/alerts?state=open&per_page=5"]),
  ]);
  const ok = (x) => !x.thrown && x.exitCode === 0;
  if (!ok(list)) {
    return { ...prev, local: next.local, repo: next.repo, status: "error", error: firstLine(list.stderr ?? list.thrown?.message) || "gh pr list failed", stale: prev.status === "ok" };
  }
  next.pr = ok(view) ? parsePrView(json(view.stdout) ?? {}) : null;
  if (!ok(view) && !NO_PR.test(view.stderr ?? "")) next.pr = prev.pr;   // a hiccup: keep what we had
  next.prs = parsePrList(json(list.stdout));
  next.reviewMe = ok(mine) ? (json(mine.stdout) ?? []).map((p) => p.number) : prev.reviewMe;
  next.runs = ok(runs) ? parseRuns(json(runs.stdout)) : prev.runs;
  next.issues = ok(issues) ? parseIssues(json(issues.stdout)) : prev.issues;
  // No access to alerts (not an admin, or turned off): leave the section out.
  next.alerts = ok(alerts) ? parseAlerts(json(alerts.stdout)) : null;
  next.status = "ok";
  next.fetchedAt = Date.now();
  return next;
}

async function unpushed(run) {
  for (const base of ["origin/HEAD", "origin/main", "origin/master"]) {
    try {
      const r = await run(["git", "rev-list", "--count", `${base}..HEAD`]);
      if (r.exitCode === 0) return Number(r.stdout.trim()) || 0;
    } catch { return null; }
  }
  return null;
}

function firstLine(text) {
  return String(text ?? "").trim().split("\n")[0].slice(0, 120);
}

// ---------------------------------------------------------------- what changed

// Toast-worthy changes between two good snapshots, as short lines.
export function diffGit(prev, next) {
  if (prev?.status !== "ok" || next?.status !== "ok" || !prev.fetchedAt) return [];
  const out = [];
  const a = prev.pr;
  const b = next.pr;
  if (a && b && a.number === b.number) {
    if (b.checks.fail > a.checks.fail) out.push(`✗ Checks failed on #${b.number}`);
    else if (a.checks.pending > 0 && b.checks.pending === 0 && b.checks.fail === 0 && b.checks.total) out.push(`✓ All checks passed on #${b.number}`);
    if (b.decision !== a.decision && b.decision === "APPROVED") out.push(`✓ #${b.number} was approved`);
    if (b.decision !== a.decision && b.decision === "CHANGES_REQUESTED") out.push(`● Changes requested on #${b.number}`);
    if (b.state !== a.state && b.state === "MERGED") out.push(`✓ #${b.number} was merged`);
    if (b.mergeable !== a.mergeable && b.mergeable === "CONFLICTING") out.push(`✗ #${b.number} has a merge conflict`);
  }
  for (const n of next.reviewMe) {
    if (prev.reviewMe.includes(n)) continue;
    const pr = next.prs.find((p) => p.number === n);
    out.push(`● ${pr?.author || "Someone"} asked for your review on #${n}${pr ? ` ${pr.title}` : ""}`);
  }
  return out;
}

// Needs a look: this branch's checks failed, or someone wants your review.
export function gitAttention(g) {
  if (g?.status !== "ok") return false;
  return (g.pr?.checks.fail ?? 0) > 0 || g.reviewMe.length > 0 || g.pr?.mergeable === "CONFLICTING";
}

export function ghStatusText(g) {
  switch (g.status) {
    case "no-gh": return "The Git room reads GitHub through the gh CLI. Install it (brew install gh), then gh auth login.";
    case "no-auth": return "gh isn't signed in. Run gh auth login in a terminal, then press r here.";
    case "no-repo": return "This session's folder isn't a git repository.";
    default: return "";
  }
}

files.hooks/sessions.mjs:
// Every Claude Code session on this computer, for the Agents room. Each
// session's mod sends a small heartbeat to its bridge, the bridge keeps it as
// a file next to the others', and every bridge reports the set back (a
// "sessions" event). Only what the room draws goes in: no prompts, no output.

import { agentTree, topTool } from "./metrics.mjs";

const FEED_SHARED = 12;

// This session's heartbeat, from its own figures.
export function heartbeat(u, { id, cwd, branch, now }) {
  const project = String(cwd ?? "").split("/").filter(Boolean).at(-1) ?? "session";
  return {
    v: 1,
    id,
    project,
    cwd,
    branch: branch ?? null,
    model: u.model,
    activity: u.activity,
    cost: u.cost?.usd ?? null,
    context: u.context?.percent ?? null,
    agents: agentTree(u).map(({ agent: a, depth, last }) => ({
      id: a.id, type: a.type, description: a.description, status: a.status,
      startedAt: a.startedAt, endedAt: a.endedAt, top: topTool(a), depth, last,
    })),
    feed: u.feed.slice(-FEED_SHARED).map((f) => ({
      key: f.key, tool: f.tool, agent: f.agentId ? (u.agents.get(f.agentId)?.type ?? "agent") : null,
      summary: f.summary, at: f.at, ms: f.ms, isError: f.isError, done: f.done,
    })),
    updatedAt: now,
  };
}

// What changed enough to send now (rather than at the next idle beat).
export function beatKey(hb) {
  return JSON.stringify([hb.activity, hb.agents.map((a) => a.status), hb.feed.at(-1)?.key, hb.feed.at(-1)?.done, Math.round((hb.cost ?? 0) * 100)]);
}

// Sessions in the order the room lists them: this one, then busy ones, then
// the rest by when they last did something.
export function orderSessions(own, others) {
  const list = [own, ...others.filter((s) => s && s.id !== own?.id)].filter(Boolean);
  const busy = (s) => ((s.activity?.state && s.activity.state !== "idle") || (s.agents ?? []).some((a) => !["completed", "failed", "killed"].includes(a.status)) ? 1 : 0);
  return list.sort((a, b) => (a === own ? -1 : b === own ? 1 : 0) || busy(b) - busy(a) || (b.activity?.since ?? 0) - (a.activity?.since ?? 0));
}

// One feed across sessions, newest last, each row naming its session.
export function mergedFeed(sessions, { filter = "all", ownId, limit = 12 } = {}) {
  const rows = [];
  for (const s of sessions) {
    if (filter === "here" && s.id !== ownId) continue;
    for (const f of s.feed ?? []) rows.push({ ...f, session: s.project, sessionId: s.id });
  }
  const kept = (filter === "errors" ? rows.filter((r) => r.isError) : rows).sort((a, b) => a.at - b.at);
  // A run of the same finished call (a subagent reading file after file
  // with one name) reads as one row with a count.
  const out = [];
  for (const r of kept) {
    const prev = out.at(-1);
    if (prev && prev.done && r.done && !r.isError && !prev.isError && prev.sessionId === r.sessionId
      && prev.agent === r.agent && prev.tool === r.tool && prev.summary === r.summary) {
      prev.times = (prev.times ?? 1) + 1;
      prev.at = r.at;
      prev.ms = r.ms;
      continue;
    }
    out.push({ ...r });
  }
  return out.slice(-limit);
}

files.hooks/focus.mjs:
// The Focus room: a Pomodoro timer. Focus for a while, then a break, each
// ending with a chime (the mod plays it). A focus round that runs out starts
// its break at once; a break that runs out waits for ▶. The lengths and the
// day's count are kept in $.store, a running timer per session, so a reload
// carries on where it was.
//
// Plain logic and drawing: the mod owns the clock, the sound and the store.

import { state } from "./state.mjs";
import { theme } from "./theme.mjs";
import { line, card, stackCards, meter } from "./widgets.mjs";
import * as K from "./bandkit.mjs";
import { draw, value, sub } from "./bands.mjs";

export const FOCUS_META = { icon: "◷", label: "Focus", color: "#E58FA8" };
const BREAK_COLOR = theme.online;

export const WORK = { min: 5, max: 120, step: 5 };
export const REST = { min: 1, max: 60, step: 1 };

export function createFocus() {
  return {
    work: 25,          // minutes of focus
    rest: 5,           // minutes of break
    phase: "idle",     // idle | focus | break
    endsAt: 0,         // while running: when the phase ends (ms)
    left: 0,           // while paused: what was left (ms)
    span: 0,           // while running: the phase's length when it began (ms)
    paused: false,
    day: "",           // the local day `done` and `focusedMs` count
    done: 0,           // focus rounds finished today
    focusedMs: 0,      // focused today, finished rounds only
    cheerAt: 0,        // when the last focus round ended (the pet cheers)
    history: {},       // "2026-10-12" → focus rounds finished that day, the last year
  };
}

// "2026-10-12" in local time: the day the count belongs to.
export function dayOf(now) {
  const d = new Date(now);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}

const DAY = /^\d{4}-\d{2}-\d{2}$/;
const KEEP_DAYS = 371;   // 53 weeks

// The day `n` days before `now`'s (noon, so a DST change can't skip one).
export function daysBefore(now, n) {
  const d = new Date(now);
  d.setHours(12, 0, 0, 0);
  d.setDate(d.getDate() - n);
  return dayOf(d.getTime());
}

// The day after "2026-10-12" (noon again, for DST).
export function dayAfter(day) {
  const [y, m, d] = day.split("-").map(Number);
  return dayOf(new Date(y, m - 1, d + 1, 12).getTime());
}

// Days in a row with a finished round, up to today (or yesterday, when
// today has none yet), and the longest run kept. Walks only the days that
// had a round, as the band asks for it every second.
export function streaks(f, now) {
  const oldest = daysBefore(now, KEEP_DAYS);
  const days = Object.keys(f.history).filter((day) => day >= oldest && f.history[day] > 0).sort();
  const had = new Set(days);
  const has = (n) => had.has(daysBefore(now, n));
  let current = 0;
  for (let n = has(0) ? 0 : 1; has(n); n++) current++;
  let best = 0, run = 0, prev = "";
  for (const day of days) {
    run = prev && dayAfter(prev) === day ? run + 1 : 1;
    best = Math.max(best, run);
    prev = day;
  }
  return { current, best };
}

function rollDay(f, now) {
  const day = dayOf(now);
  if (f.day !== day) { f.day = day; f.done = 0; f.focusedMs = 0; }
}

const phaseMs = (f, phase = f.phase) => (phase === "break" ? f.rest : f.work) * 60_000;
// The running phase's own length: −/+ meanwhile is for the next one.
const spanMs = (f) => f.span || phaseMs(f);

export function isRunning(f) {
  return f.phase !== "idle" && !f.paused;
}

// What's left of the phase, in ms (the whole focus length while idle).
export function remaining(f, now) {
  if (f.phase === "idle") return phaseMs(f, "focus");
  if (f.paused) return f.left;
  return Math.max(0, f.endsAt - now);
}

// How far through the phase, 0 to 1.
export function progress(f, now) {
  if (f.phase === "idle") return 0;
  return Math.min(1, Math.max(0, 1 - remaining(f, now) / spanMs(f)));
}

// "18:42", or "1:05:00" past an hour.
export function clock(ms) {
  const s = Math.ceil(ms / 1000);
  const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60), sec = s % 60;
  const mm = String(m).padStart(h ? 2 : 1, "0"), ss = String(sec).padStart(2, "0");
  return h ? `${h}:${mm}:${ss}` : `${mm.padStart(2, "0")}:${ss}`;
}

// ▶: start a focus round, or carry on after a pause.
export function start(f, now) {
  rollDay(f, now);
  if (f.paused) { f.paused = false; f.endsAt = now + f.left; f.left = 0; return; }
  if (f.phase === "idle") { f.phase = "focus"; f.span = phaseMs(f); f.endsAt = now + f.span; }
}

export function pause(f, now) {
  if (!isRunning(f)) return;
  f.left = Math.max(0, f.endsAt - now);
  f.paused = true;
}

// ↺: back to idle, the round not counted.
export function reset(f) {
  f.phase = "idle";
  f.paused = false;
  f.endsAt = 0;
  f.left = 0;
  f.span = 0;
}

// The phase is over: a focus round counts and its break starts; a break
// goes back to idle. Returns what ended ("focus" or "break").
function finish(f, now, { counted }) {
  const ended = f.phase;
  if (ended === "focus") {
    rollDay(f, now);
    if (counted) {
      f.done += 1;
      f.focusedMs += spanMs(f);
      f.cheerAt = now;
      f.history[f.day] = (f.history[f.day] ?? 0) + 1;
      const oldest = daysBefore(now, KEEP_DAYS);
      for (const day of Object.keys(f.history)) if (day < oldest) delete f.history[day];
    }
    f.phase = "break";
    f.paused = false;
    f.span = phaseMs(f, "break");
    f.endsAt = now + f.span;
    f.left = 0;
  } else reset(f);
  return ended;
}

// ⏭: end the phase now. A focus round skipped doesn't count.
export function skip(f, now) {
  if (f.phase === "idle") return null;
  return finish(f, now, { counted: false });
}

// Once a second: the phase that ran out, or null.
export function tickFocus(f, now) {
  if (!isRunning(f) || now < f.endsAt) return null;
  return finish(f, now, { counted: true });
}

// −/+ on a length. A running phase keeps its end; the new length is for the next.
export function adjust(f, which, dir) {
  const r = which === "rest" ? REST : WORK;
  const v = Math.min(r.max, Math.max(r.min, f[which] + dir * r.step));
  f[which] = v;
}

// "50 10", "50/10" or "50": the lengths, typed. True when it was that.
export function setLengths(f, text) {
  const m = /^(\d{1,3})(?:\s*[\s/]\s*(\d{1,3}))?$/.exec(String(text ?? "").trim());
  if (!m) return false;
  f.work = Math.min(WORK.max, Math.max(WORK.min, Number(m[1])));
  if (m[2]) f.rest = Math.min(REST.max, Math.max(REST.min, Number(m[2])));
  return true;
}

// What's kept in $.store: the lengths and today's count (shared by every
// session), and the running timer (this session's).
export function focusSettings(f) {
  return { work: f.work, rest: f.rest, day: f.day, done: f.done, focusedMs: f.focusedMs, history: f.history };
}
export function focusTimer(f) {
  return { phase: f.phase, endsAt: f.endsAt, left: f.left, paused: f.paused, span: f.span };
}

// A running phase whose end passed this long ago ran out while no session
// was there to see it: it isn't counted or chimed for, only let go.
const STALE_MS = 60_000;
export function restoreFocus(f, settings, timer, now) {
  if (settings && typeof settings === "object") {
    if (Number.isFinite(settings.work)) f.work = Math.min(WORK.max, Math.max(WORK.min, settings.work));
    if (Number.isFinite(settings.rest)) f.rest = Math.min(REST.max, Math.max(REST.min, settings.rest));
    if (typeof settings.day === "string") { f.day = settings.day; f.done = settings.done | 0; f.focusedMs = settings.focusedMs | 0; }
    if (settings.history && typeof settings.history === "object") {
      f.history = Object.fromEntries(Object.entries(settings.history).filter(([day, n]) => DAY.test(day) && Number.isInteger(n) && n > 0));
    }
  }
  if (timer && ["focus", "break"].includes(timer.phase)) {
    const paused = timer.paused === true;
    const endsAt = Number(timer.endsAt) || 0;
    if (paused || now - endsAt < STALE_MS) {
      f.phase = timer.phase;
      f.paused = paused;
      f.endsAt = endsAt;
      f.left = Number(timer.left) || 0;
      f.span = Number(timer.span) || 0;
    }
  }
  rollDay(f, now);
}

// ---------------------------------------------------------------- drawing

const phaseWord = (f) => (f.phase === "break" ? "break" : f.phase === "focus" ? "focus" : "ready");
const phaseColor = (f) => (f.phase === "break" ? BREAK_COLOR : FOCUS_META.color);
export const spent = (ms) => {
  const m = Math.round(ms / 60_000);
  return m >= 60 ? `${Math.floor(m / 60)}h ${m % 60}m` : `${m}m`;
};

// The ring, drawn: the track, the arc gone so far, the time and the phase.
function ring(els, f, now) {
  const size = 132, r = 54, c = 2 * Math.PI * r;
  const color = phaseColor(f);
  const left = c * (1 - progress(f, now));
  const sub = f.phase === "idle" ? `${f.work} / ${f.rest} min` : `${phaseWord(f)}${f.paused ? " · paused" : ""}`;
  const source = `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 ${size} ${size}" font-family="-apple-system, system-ui, sans-serif">`
    + `<circle cx="66" cy="66" r="${r}" fill="none" stroke="rgba(127,127,127,0.25)" stroke-width="9"/>`
    + (f.phase === "idle" ? "" : `<circle cx="66" cy="66" r="${r}" fill="none" stroke="${color}" stroke-width="9" stroke-linecap="round" stroke-dasharray="${c.toFixed(1)}" stroke-dashoffset="${left.toFixed(1)}" transform="rotate(-90 66 66)"/>`)
    + `<text x="66" y="70" text-anchor="middle" font-size="28" font-weight="600" fill="${f.paused ? "#9A968F" : "#ECE7E1"}">${clock(remaining(f, now))}</text>`
    + `<text x="66" y="92" text-anchor="middle" font-size="12" fill="#9A968F">${sub}</text></svg>`;
  return els.Svg({ key: "ring", source, alt: `${clock(remaining(f, now))} ${sub}`, width: size, height: size });
}

function controls(els, f, handlers) {
  const { Box, Button } = els;
  const main = f.phase === "idle" ? { label: "▶ Start", fn: "onFocusStart" }
    : f.paused ? { label: "▶ Resume", fn: "onFocusStart" }
      : { label: "⏸ Pause", fn: "onFocusPause" };
  return Box({ key: "controls", flexDirection: "row", justifyContent: "center", columnGap: 1, children: [
    Button({ key: "focus-main", label: main.label, variant: "primary", onPress: () => handlers[main.fn]?.() }),
    f.phase === "idle" ? null : Button({ key: "focus-skip", label: f.phase === "focus" ? "⏭ Break" : "⏭ Skip", onPress: () => handlers.onFocusSkip?.() }),
    f.phase === "idle" ? null : Button({ key: "focus-reset", label: "↺", onPress: () => handlers.onFocusReset?.() }),
  ].filter(Boolean) });
}

function timerCard(els, f, w, handlers, now) {
  const { Box, Text } = els;
  const color = phaseColor(f);
  const rows = [];
  if (els.Svg) {
    rows.push(Box({ key: "ring-row", flexDirection: "row", justifyContent: "center", children: [ring(els, f, now)] }));
  } else {
    rows.push(line(els, "time", [
      { text: clock(remaining(f, now)), bold: true, color: f.paused ? theme.muted : color },
      { text: `  ${phaseWord(f)}${f.paused ? " · paused" : ""}`, color: theme.muted, grow: true },
    ]));
    rows.push(meter(els, { key: "bar", label: f.phase === "break" ? "Break" : "Focus", pct: progress(f, now) * 100, width: w, color, right: `${Math.round(spanMs(f) / 60_000)} min` }));
  }
  rows.push(controls(els, f, handlers));
  const meta = f.done ? `${f.done} done today` : "none done today";
  return { name: "Timer", node: card(els, { key: "timer", title: f.phase === "break" ? "BREAK" : "FOCUS", color, meta, rows }), height: 3 + (els.Svg ? 7 : rows.length) };
}

function lengthRow(els, key, label, value, handlers) {
  const { Box, Text, Button } = els;
  return Box({ key, flexDirection: "row", alignItems: "center", children: [
    Box({ key: "l", flexGrow: 1, children: [Text({ key: "t", children: label })] }),
    // The value in a box of its own width, so −, the value and + line up
    // from one row to the next whatever the number.
    Box({ key: "ctl", flexDirection: "row", alignItems: "center", columnGap: 1, flexShrink: 0, children: [
      Button({ key: `${key}-less`, label: "−", onPress: () => handlers.onFocusAdjust?.(key, -1) }),
      Box({ key: "v", width: 8, flexShrink: 0, justifyContent: "center", children: [Text({ key: "t", bold: true, children: `${value} min` })] }),
      Button({ key: `${key}-more`, label: "+", onPress: () => handlers.onFocusAdjust?.(key, 1) }),
    ] }),
  ] });
}

function settingsCard(els, f, handlers) {
  const rows = [lengthRow(els, "work", "Focus", f.work, handlers), lengthRow(els, "rest", "Break", f.rest, handlers)];
  const meta = f.focusedMs ? `${spent(f.focusedMs)} focused today` : "";
  return { name: "Settings", node: card(els, { key: "settings", title: "SETTINGS", color: FOCUS_META.color, meta, rows }), height: 3 + rows.length };
}

// The streak, as GitHub draws contributions: a column a week, Sunday at
// the top, today last, each day's square darker the more rounds it had.
const LEVELS = [0.18, 0.4, 0.62, 0.84, 1];
function level(n) {
  return n <= 0 ? 0 : n === 1 ? 1 : n <= 3 ? 2 : n <= 5 ? 3 : 4;
}
function streakGrid(f, now, weeks) {
  const today = new Date(now).getDay();   // 0 Sunday
  const cols = [];
  for (let wk = weeks - 1; wk >= 0; wk--) {
    const col = [];
    for (let dow = 0; dow < 7; dow++) {
      const back = wk * 7 + (today - dow);
      col.push(back < 0 ? null : f.history[daysBefore(now, back)] ?? 0);
    }
    cols.push(col);
  }
  return cols;
}

// A month's short name over the week it starts in, as GitHub sets them; one
// too close to the last (the first column's, mostly) is left out.
function monthLabels(now, weeks, step) {
  const today = new Date(now).getDay();
  let out = "", lastMonth = -1, lastX = -99;
  for (let wk = weeks - 1, x = 0; wk >= 0; wk--, x++) {
    const d = new Date(now);
    d.setHours(12, 0, 0, 0);
    d.setDate(d.getDate() - (wk * 7 + today));   // the week's Sunday
    const m = d.getMonth();
    if (m !== lastMonth && x * step - lastX >= 30) {
      out += `<text x="${x * step}" y="10" font-size="10" fill="#9A968F">${d.toLocaleDateString("en-US", { month: "short" })}</text>`;
      lastX = x * step;
    }
    lastMonth = m;
  }
  return out;
}

function streakCard(els, f, w, now) {
  const { Box, Text } = els;
  const { current, best } = streaks(f, now);
  const meta = current ? `🔥 ${current} day${current === 1 ? "" : "s"} · best ${best}` : best ? `best ${best} days` : "";
  const rose = FOCUS_META.color;
  let rows;
  if (els.Svg) {
    // GitHub's: the months along the top, the squares, then the total and a
    // Less-to-More legend under them.
    const weeks = Math.max(12, Math.min(26, Math.floor((w * 8) / 14)));
    const cell = 11, gap = 3, step = cell + gap, top = 15;
    const grid = streakGrid(f, now, weeks);
    const squares = grid.flatMap((col, x) => col.map((n, y) => (n == null ? "" : `<rect x="${x * step}" y="${top + y * step}" width="${cell}" height="${cell}" rx="2.5" fill="${n ? rose : "#8F8D87"}" fill-opacity="${LEVELS[level(n ?? 0)]}"/>`))).join("");
    const W = weeks * step - gap, H = top + 7 * step - gap;
    const total = grid.flat().reduce((a, n) => a + (n ?? 0), 0);
    const legend = `<svg xmlns="http://www.w3.org/2000/svg" width="112" height="14" viewBox="0 0 112 14" font-family="-apple-system, system-ui, sans-serif">`
      + `<text x="0" y="11" font-size="11" fill="#9A968F">Less</text>`
      + LEVELS.map((o, i) => `<rect x="${28 + i * 12}" y="2" width="10" height="10" rx="2" fill="${i ? rose : "#8F8D87"}" fill-opacity="${o}"/>`).join("")
      + `<text x="${28 + 5 * 12 + 2}" y="11" font-size="11" fill="#9A968F">More</text></svg>`;
    rows = [
      els.Svg({ key: "streak", source: `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}" font-family="-apple-system, system-ui, sans-serif">${monthLabels(now, weeks, step)}${squares}</svg>`, alt: `${total} focus rounds in the last ${weeks} weeks`, width: W, height: H }),
      Box({ key: "foot", flexDirection: "row", alignItems: "center", children: [
        Box({ key: "sum", flexGrow: 1, children: [Text({ key: "t", color: theme.muted, children: `${total} round${total === 1 ? "" : "s"} in ${weeks} weeks` })] }),
        els.Svg({ key: "legend", source: legend, alt: "Less to more rounds", width: 112, height: 14 }),
      ] }),
    ];
  } else {
    // A square and a space a day: as many weeks as the card holds.
    const weeks = Math.max(4, Math.min(26, Math.floor((w - 1) / 2)));
    const grid = streakGrid(f, now, weeks);
    rows = Array.from({ length: 7 }, (_, dow) => Box({ key: `d${dow}`, flexDirection: "row", children: grid.map((col, x) => {
      const n = col[dow];
      return Text({ key: `c${x}`, color: n ? rose : theme.muted, dimColor: !n || level(n) < 2, children: n == null ? "  " : n ? "■ " : "· " });
    }) }));
  }
  return { name: "Streak", node: card(els, { key: "streak", title: "STREAK", color: FOCUS_META.color, meta, rows }), height: 3 + (els.Svg ? 8 : 7) };
}

export function focusDock(els, w, capacity, handlers, now) {
  const f = state.focus;
  return stackCards(els, [timerCard(els, f, w, handlers, now), settingsCard(els, f, handlers), streakCard(els, f, w, now)], capacity, handlers.scroll);
}

export function focusInline(els, w, handlers, now) {
  const f = state.focus;
  const { Box, Button } = els;
  return [
    line(els, "head", [
      { text: `${FOCUS_META.icon} ${FOCUS_META.label}`, bold: true, color: FOCUS_META.color },
      { text: `  ${clock(remaining(f, now))}`, bold: true, color: phaseColor(f) },
      { text: `  ${phaseWord(f)}${f.paused ? " · paused" : ""}`, color: theme.muted, grow: true },
      { text: `${f.done} today`, color: theme.muted },
    ]),
    meter(els, { key: "bar", label: `${f.work}/${f.rest} min`, pct: progress(f, now) * 100, width: w, color: phaseColor(f) }),
    controls(els, f, handlers),
  ];
}

const hhmm = (ms) => { const d = new Date(ms); return `${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}`; };
const phaseLabel = (f) => (f.phase === "break" ? "☕ Break" : f.phase === "focus" ? "🍅 Focus" : "Ready");
// What comes after the phase on show.
function nextText(f, now) {
  if (f.phase === "break") return `next: round ${f.done + 1} · ${f.work} min`;
  if (f.phase === "focus") return f.paused ? `${f.rest} min break after` : `ends ${hhmm(now + remaining(f, now))}`;
  return `${f.work} / ${f.rest} min`;
}

// The terminal's band: "☕ Break 03:12 · 🔥 5 days · next: round 4 · 25 min".
export function focusBandPieces() {
  const f = state.focus;
  const now = Date.now();
  const { current } = streaks(f, now);
  const sep = { text: " · ", color: theme.muted };
  return [
    { text: phaseLabel(f), color: phaseColor(f), bold: true },
    f.phase === "idle" ? null : { text: ` ${clock(remaining(f, now))}${f.paused ? " ⏸" : ""}`, color: phaseColor(f), bold: true },
    current ? sep : null,
    current ? { text: `🔥 ${current} day${current === 1 ? "" : "s"}`, color: theme.amber, bold: true } : null,
    sep,
    { text: nextText(f, now), color: theme.muted },
  ].filter(Boolean);
}

// The desktop's band, as sections for the capsule: the phase and its time,
// ten cells for how far it has gone, the streak with this week's days, and
// what comes next. The capsule takes the phase's color: green in a break.
export function focusBandDesk(now = Date.now()) {
  const f = state.focus;
  const color = phaseColor(f);
  const { current, best } = streaks(f, now);
  const pct = progress(f, now) * 100;
  const week = Array.from({ length: 7 }, (_, i) => f.history[daysBefore(now, 6 - i)] ?? 0);
  const squares = { source: K.svg(63, 9, week.map((n, i) => `<rect x="${i * 9}" y="1" width="7" height="7" rx="1.5" fill="${n ? FOCUS_META.color : "#8F8D87"}" fill-opacity="${LEVELS[level(n)]}"/>`).join("")), width: 63, height: 9 };
  const sections = [
    { key: "phase", color, parts: [value(phaseLabel(f), color), f.phase === "idle" ? null : value(`${clock(remaining(f, now))}${f.paused ? " ⏸" : ""}`)],
      tip: [`Focus ${f.work} min · Break ${f.rest} min`, `${f.done} round${f.done === 1 ? "" : "s"} done today`] },
    f.phase === "idle" ? null : { key: "progress", color, parts: [draw(K.cells(pct, color, { n: 10 }), `${Math.round(pct)}% through`)] },
    { key: "streak", color: theme.amber, parts: [current ? value(`🔥 ${current} day${current === 1 ? "" : "s"}`, theme.amber) : sub("no streak yet"), draw(squares, "This week"), sub("this week")],
      tip: [current ? `${current} day${current === 1 ? "" : "s"} in a row` : "Finish a round today to start one", `best ${best} day${best === 1 ? "" : "s"}`] },
    { key: "next", color, parts: [sub(nextText(f, now))] },
  ];
  return { color, sections: sections.filter(Boolean) };
}

export function focusStatus(now = Date.now()) {
  const f = state.focus;
  if (f.phase === "idle") return "";
  return `${f.phase === "break" ? "☕" : "🍅"} ${clock(remaining(f, now))}${f.paused ? " ⏸" : ""}`;
}

// The tab's badge from another room: minutes left while running.
export function focusBadge(now = Date.now()) {
  const f = state.focus;
  if (f.phase === "idle") return null;
  return { text: f.paused ? "⏸" : `${Math.ceil(remaining(f, now) / 60_000)}m`, color: phaseColor(f) };
}

export function focusSnapshot(now = Date.now()) {
  const f = state.focus;
  const left = clock(remaining(f, now));
  const head = f.phase === "idle" ? `Ready to focus (${f.work} / ${f.rest} min).`
    : f.phase === "break" ? `On a break, ${left} left${f.paused ? ", paused" : ""}.`
    : `Focusing, ${left} to go of ${Math.round(spanMs(f) / 60_000)} min${f.paused ? ", paused" : ""}.`;
  const today = f.done ? `${f.done} round${f.done === 1 ? "" : "s"} today, ${spent(f.focusedMs)} focused.` : "No rounds yet today.";
  const { current } = streaks(f, now);
  return `◷ ${head} ${today}${current ? ` 🔥 ${current}-day streak.` : ""}`;
}

