// The terminal's symbols, and open-meteo's, to a drawing.
const WEATHER_OF = { "☾": "moon", "≡": "fog", "☀": "sun", "☁": "cloud", "☂": "umbrella", "☇": "storm", "↯": "compact", "⛅": "partly", "🌤": "partly", "🌧": "rain", "🌦": "rain", "❄": "snow", "🌨": "snow", "⛈": "storm", "🌫": "fog" };
