  shade: "#B85E40",
  band: "#24408C",
  cup: "#1E3478",
  cupHi: "#7FA4E8",
  eye: "#141414",
  blush: "#F08C8C",
  gold: "#FABE28",
  note: "#7FA4E8",
  red: "#E6465A",
  z: "#8FA6E0",
